<?php

declare(strict_types=1);

namespace App\Models;

use App\Support\Ids\HasPrefixedId;
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string|null $listing_id
 * @property string $buyer_id
 * @property string $seller_id
 * @property string|null $last_message_preview
 * @property Carbon|null $last_message_at
 * @property Carbon|null $buyer_last_read_at
 * @property Carbon|null $seller_last_read_at
 * @property Carbon|null $buyer_notified_at
 * @property Carbon|null $seller_notified_at
 * @property bool $is_flagged
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Conversation extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'cnv';

    protected $fillable = [
        'listing_id', 'buyer_id', 'seller_id', 'last_message_preview', 'last_message_at', 'buyer_last_read_at',
        'seller_last_read_at', 'buyer_notified_at', 'seller_notified_at', 'is_flagged',
    ];

    protected function casts(): array
    {
        return [
            'last_message_at' => 'datetime',
            'buyer_last_read_at' => 'datetime',
            'seller_last_read_at' => 'datetime',
            'buyer_notified_at' => 'datetime',
            'seller_notified_at' => 'datetime',
            'is_flagged' => 'boolean',
        ];
    }

    /** @return BelongsTo<Listing, $this> */
    public function listing(): BelongsTo
    {
        return $this->belongsTo(Listing::class)->withTrashed();
    }

    /** @return BelongsTo<User, $this> */
    public function buyer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'buyer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function seller(): BelongsTo
    {
        return $this->belongsTo(User::class, 'seller_id');
    }

    /** @return HasMany<Message, $this> */
    public function messages(): HasMany
    {
        return $this->hasMany(Message::class);
    }

    public function scopeForParticipant(Builder $query, User $user): Builder
    {
        return $query->where(fn (Builder $q) => $q->where('buyer_id', $user->id)->orWhere('seller_id', $user->id));
    }

    public function isParticipant(User $user): bool
    {
        return $user->id === $this->buyer_id || $user->id === $this->seller_id;
    }

    public function otherParticipantId(User $user): string
    {
        return $user->id === $this->buyer_id ? $this->seller_id : $this->buyer_id;
    }

    public function lastReadAtFor(User $user): ?Carbon
    {
        return $user->id === $this->buyer_id ? $this->buyer_last_read_at : $this->seller_last_read_at;
    }
}
